def count_tilings(grid: list[str]) -> int:
    if not grid:
        return 1

    rows = len(grid)
    cols = len(grid[0])

    for row in grid:
        if len(row) != cols:
            raise ValueError("all rows must have the same length")
        for ch in row:
            if ch != "." and ch != "#":
                raise ValueError("cells must be '.' or '#'")

    if cols == 0:
        return 1

    # Keep the profile width as small as possible.
    if cols > rows:
        grid = ["".join(grid[r][c] for r in range(rows)) for c in range(cols)]
        rows, cols = cols, rows

    total = rows * cols
    if total == 0:
        return 1

    free = [ch == "." for row in grid for ch in row]

    # A piece placed at p can occupy cells up to p + cols + 1.
    state_len = cols + 2
    state_count = 1 << state_len

    placements = []
    for p in range(total):
        if not free[p]:
            placements.append(())
            continue

        r, c = divmod(p, cols)
        opts = []

        def add_offsets(offsets):
            mask = 0
            for off in offsets:
                if off < 0 or p + off >= total or not free[p + off]:
                    return
                mask |= 1 << off
            opts.append(mask)

        # Horizontal domino
        if c + 1 < cols:
            add_offsets((0, 1))

        # Vertical domino
        if r + 1 < rows:
            add_offsets((0, cols))

        # L-trominoes whose top-left cell is the current cell.
        if c + 1 < cols and r + 1 < rows:
            # Missing bottom-left: current, right, bottom-right
            add_offsets((0, 1, cols + 1))
            # Missing bottom-right: current, right, bottom
            add_offsets((0, 1, cols))
            # Missing top-right: current, bottom, bottom-right
            add_offsets((0, cols, cols + 1))

        # L-tromino missing the top-left cell.
        # The current cell is the top-right cell of the 2x2 block.
        if c > 0 and r + 1 < rows:
            # Missing top-left: current, bottom-left, bottom-right
            add_offsets((0, cols - 1, cols))

        placements.append(tuple(opts))

    dp = [0] * state_count
    dp[0] = 1

    for p in range(total):
        ndp = [0] * state_count
        blocked = not free[p]
        opts = placements[p]

        if blocked:
            for state, val in enumerate(dp):
                if val and not (state & 1):
                    ndp[state >> 1] += val
        else:
            for state, val in enumerate(dp):
                if not val:
                    continue

                if state & 1:
                    ndp[state >> 1] += val
                else:
                    for mask in opts:
                        if state & mask == 0:
                            ndp[(state | mask) >> 1] += val

        dp = ndp

    return dp[0]
